test("P96 WebRTC digital human avatar multi-stream lip-sync (ITU-R BT.1359-1) & RTCP SR NTP wallclock drift guard re-anchors stale RTCP SR, decouples >180ms video stalls, and clamps AV skew", () => {
  // 1. RTCP Sender Report age >5000ms or NTP wallclock step jump >500ms -> decouple audio clock from stale RTCP SR
  const rtcpDesync = evaluateWebRtcAvLipSyncSkewAndRtcpSrWallclockGuard({
    callId: "call-p96-rtcp-01",
    audioPlayoutTimestampMs: 12000,
    videoVisemeRenderTimestampMs: 12010,
    rtcpSenderReportAgeMs: 6400,
    ntpWallclockStepJumpMs: 650,
    appliedAudioDelayBufferMs: 20,
  });
  assert.equal(rtcpDesync.allowed, false);
  assert.equal(rtcpDesync.lipSyncWithinItuBt1359Window, false);
  assert.equal(rtcpDesync.decoupleAudioFromStalledVideo, true);
  assert.equal(
    rtcpDesync.actionCode,
    "DECOUPLE_AUDIO_CLOCK_FROM_STALE_RTCP_SR_AND_RESET_RTP_NTP_CORRELATION"
  );
  assert.equal(
    rtcpDesync.reason,
    "RTCP_SR_RFC3550_NTP_WALLCLOCK_STALE_OR_STEP_JUMP_DESYNC"
  );
  assert.equal(
    rtcpDesync.policyCode,
    "P96-WEBRTC-RTP-MULTI-STREAM-LIPSYNC-AV-SKEW-ITU-R-BT1359-RTCP-SR-NTP-WALLCLOCK-DRIFT-GUARD"
  );

  // 2. Avatar video viseme render lags audio by >180ms -> decouple avatar video to static idle loop & release audio immediately
  const avatarStall = evaluateWebRtcAvLipSyncSkewAndRtcpSrWallclockGuard({
    callId: "call-p96-stall-02",
    audioPlayoutTimestampMs: 15000,
    videoVisemeRenderTimestampMs: 15240,
    rtcpSenderReportAgeMs: 900,
    ntpWallclockStepJumpMs: 2,
    appliedAudioDelayBufferMs: 20,
  });
  assert.equal(avatarStall.allowed, false);
  assert.equal(avatarStall.lipSyncWithinItuBt1359Window, false);
  assert.equal(avatarStall.decoupleAudioFromStalledVideo, true);
  assert.equal(avatarStall.measuredAvSkewMs, -220);
  assert.equal(
    avatarStall.actionCode,
    "DETACH_STALLED_AVATAR_VIDEO_SWITCH_TO_IDLE_LOOP_AND_PLAY_OPUS_AUDIO_IMMEDIATELY"
  );
  assert.equal(
    avatarStall.reason,
    "AVATAR_VIDEO_RENDER_STALL_EXCEEDS_180MS_VOICE_INTERACTIVITY_BUDGET"
  );

  // 3. Moderate lip-sync skew outside ITU-R BT.1359-1 [-45ms, +125ms] window -> adjust audio playout delay buffer
  const skewOutOfBounds = evaluateWebRtcAvLipSyncSkewAndRtcpSrWallclockGuard({
    callId: "call-p96-skew-03",
    audioPlayoutTimestampMs: 18000,
    videoVisemeRenderTimestampMs: 18110,
    rtcpSenderReportAgeMs: 1100,
    ntpWallclockStepJumpMs: 3,
    appliedAudioDelayBufferMs: 20,
  });
  assert.equal(skewOutOfBounds.allowed, false);
  assert.equal(skewOutOfBounds.lipSyncWithinItuBt1359Window, false);
  assert.equal(skewOutOfBounds.decoupleAudioFromStalledVideo, false);
  assert.equal(skewOutOfBounds.measuredAvSkewMs, -90);
  assert.equal(
    skewOutOfBounds.actionCode,
    "INJECT_BOUNDED_AUDIO_DELAY_BUFFER_OR_DROP_LATE_VISEME_FRAMES_TO_RESTORE_BT1359"
  );
  assert.equal(
    skewOutOfBounds.reason,
    "ITU_R_BT1359_AV_LIPSYNC_SKEW_THRESHOLD_EXCEEDED"
  );

  // 4. Lip-sync skew within ITU-R BT.1359-1 [-45ms, +125ms] and healthy RTCP SR -> maintain synchronized avatar stream
  const syncedAvatar = evaluateWebRtcAvLipSyncSkewAndRtcpSrWallclockGuard({
    callId: "call-p96-valid-04",
    audioPlayoutTimestampMs: 20000,
    videoVisemeRenderTimestampMs: 20030,
    rtcpSenderReportAgeMs: 800,
    ntpWallclockStepJumpMs: 1,
    appliedAudioDelayBufferMs: 20,
  });
  assert.equal(syncedAvatar.allowed, true);
  assert.equal(syncedAvatar.lipSyncWithinItuBt1359Window, true);
  assert.equal(syncedAvatar.measuredAvSkewMs, -10);
  assert.equal(
    syncedAvatar.actionCode,
    "MAINTAIN_SYNCHRONIZED_MULTIMODAL_AVATAR_PLAYOUT"
  );
  assert.equal(
    syncedAvatar.reason,
    "ITU_R_BT1359_LIPSYNC_WINDOW_AND_RTCP_SR_WALLCLOCK_VERIFIED"
  );
});

