test("P106 SIP/RTP symmetric latching hijack & port exhaustion mux guard blocks unauthenticated RTP bleed, reaps pre-answer pinholes at >=85% port pool utilization, and enforces RFC 5761 rtcp-mux", () => {
  // 1. Source IP:Port changes mid-call without valid SRTP HMAC/AEAD auth tag or matching SDP subnet -> drop spoofed packet and keep original latch
  const hijackBlocked = evaluateSipRtpSymmetricLatchingHijackAndPortExhaustionMuxGuard({
    sessionId: "call-p106-bleed-01",
    inboundRtpSourceAddressChanged: true,
    remotePacketSourceIpMatchesSignaledSdpSubnet: false,
    srtpAuthTagVerifiedBeforeLatchUpdate: false,
    sbcUdpPortPoolUtilizationPercent: 48,
    rtcpMuxRfc5761Negotiated: true,
    callAnswered200Ok: true,
    preAnswerPortReservedDurationMs: 8000,
    maxAllowedPreAnswerPortHoldMs: 30000,
  });
  assert.equal(hijackBlocked.allowed, false);
  assert.equal(hijackBlocked.mediaPlaneLatchSecure, false);
  assert.equal(hijackBlocked.rtcpMuxSinglePortActive, true);
  assert.equal(
    hijackBlocked.actionCode,
    "DROP_SPOOFED_UDP_PACKET_LOCK_EXISTING_SRTP_PINHOLE_AND_REQUIRE_CRYPTOGRAPHIC_AUTH_TAG_BEFORE_LATCH"
  );
  assert.equal(
    hijackBlocked.reason,
    "SYMMETRIC_RTP_UNAUTHENTICATED_PINHOLE_HIJACK_OR_RTP_BLEED_BLOCKED"
  );
  assert.equal(
    hijackBlocked.policyCode,
    "P106-SIP-RTP-PORT-EXHAUSTION-SYMMETRIC-LATCHING-NAT-REBIND-PINHOLE-HIJACK-AND-RTCP-MUX-GUARD"
  );

  // 2. SBC UDP port pool utilization >= 85% without rtcp-mux or pre-answer early media > 30s -> enforce RFC 5761 rtcp-mux and reap half-open pinholes
  const portPoolProtected = evaluateSipRtpSymmetricLatchingHijackAndPortExhaustionMuxGuard({
    sessionId: "call-p106-pool-02",
    inboundRtpSourceAddressChanged: false,
    remotePacketSourceIpMatchesSignaledSdpSubnet: true,
    srtpAuthTagVerifiedBeforeLatchUpdate: true,
    sbcUdpPortPoolUtilizationPercent: 89,
    rtcpMuxRfc5761Negotiated: false,
    callAnswered200Ok: false,
    preAnswerPortReservedDurationMs: 42000,
    maxAllowedPreAnswerPortHoldMs: 30000,
  });
  assert.equal(portPoolProtected.allowed, false);
  assert.equal(portPoolProtected.portPoolHealthy, false);
  assert.equal(portPoolProtected.rtcpMuxSinglePortActive, false);
  assert.equal(
    portPoolProtected.actionCode,
    "ENFORCE_RFC5761_RTCP_MUX_SINGLE_PORT_REAP_STALE_PREANSWER_RESERVATIONS_AND_SPILL_TO_SECONDARY_MEDIA_POOL"
  );
  assert.equal(
    portPoolProtected.reason,
    "RTP_PORT_POOL_HIGH_WATERMARK_RTCP_MUX_ENFORCED_AND_PREANSWER_REAPED"
  );

  // 3. Cryptographically verified SRTP latch, rtcp-mux active, and port pool utilization < 85% -> allow media
  const healthyMedia = evaluateSipRtpSymmetricLatchingHijackAndPortExhaustionMuxGuard({
    sessionId: "call-p106-valid-03",
    inboundRtpSourceAddressChanged: true,
    remotePacketSourceIpMatchesSignaledSdpSubnet: true,
    srtpAuthTagVerifiedBeforeLatchUpdate: true,
    sbcUdpPortPoolUtilizationPercent: 52,
    rtcpMuxRfc5761Negotiated: true,
    callAnswered200Ok: true,
    preAnswerPortReservedDurationMs: 6000,
    maxAllowedPreAnswerPortHoldMs: 30000,
  });
  assert.equal(healthyMedia.allowed, true);
  assert.equal(healthyMedia.mediaPlaneLatchSecure, true);
  assert.equal(healthyMedia.portPoolHealthy, true);
  assert.equal(healthyMedia.rtcpMuxSinglePortActive, true);
  assert.equal(
    healthyMedia.actionCode,
    "PERMIT_AUTHENTICATED_SRTP_MEDIA_FLOW_WITH_SINGLE_PORT_RTCP_MUX"
  );
  assert.equal(
    healthyMedia.reason,
    "CRYPTOGRAPHIC_SRTP_LATCH_VERIFIED_AND_RFC5761_RTCP_MUX_PORT_POOL_HEALTHY"
  );
});

