test("P110 WebRTC SCTP DataChannel (RFC 8831) transcript backpressure, unordered HoL-blocking prevention & heartbeat watchdog guard enforces unordered zero-retransmit interim transcripts, sheds backpressure, and fails over zombie SCTP streams", () => {
  // 1. Interim transcript configured on ordered/reliable SCTP DataChannel -> block HoL misconfiguration
  const holBlocked = evaluateWebRtcSctpDataChannelBackpressureAndHoLWatchdogGuard({
    sessionId: "call-p110-hol-01",
    payloadCategory: "INTERIM_TRANSCRIPT",
    dataChannelOrdered: true,
    dataChannelMaxRetransmits: null,
    bufferedAmountBytes: 12000,
    maxAllowedBufferedAmountBytes: 65536,
    srtpAudioQueueDelayMs: 18,
    sctpHeartbeatSilenceMs: 410,
    sctpSmoothedRttMs: 85,
  });
  assert.equal(holBlocked.allowed, false);
  assert.equal(holBlocked.ephemeralReliabilityConfigured, false);
  assert.equal(
    holBlocked.actionCode,
    "ENFORCE_RFC8831_UNORDERED_ZERO_RETRANSMIT_DATACHANNEL_FOR_EPHEMERAL_TRANSCRIPTS"
  );
  assert.equal(
    holBlocked.reason,
    "WEBRTC_SCTP_INTERIM_TRANSCRIPT_ORDERED_RELIABLE_HEAD_OF_LINE_BLOCKING_MISCONFIGURATION"
  );
  assert.equal(
    holBlocked.policyCode,
    "P110-WEBRTC-SCTP-DATACHANNEL-TRANSCRIPT-BACKPRESSURE-HEAD-OF-LINE-STALL-AND-HEARTBEAT-WATCHDOG-GUARD"
  );

  // 2. SCTP bufferedAmount overflow (128KB > 64KB) or SRTP audio queue delay > 60ms -> shed interim transcripts and prioritize DSCP EF audio
  const backpressureShed = evaluateWebRtcSctpDataChannelBackpressureAndHoLWatchdogGuard({
    sessionId: "call-p110-bp-02",
    payloadCategory: "INTERIM_TRANSCRIPT",
    dataChannelOrdered: false,
    dataChannelMaxRetransmits: 0,
    bufferedAmountBytes: 131072,
    maxAllowedBufferedAmountBytes: 65536,
    srtpAudioQueueDelayMs: 74,
    sctpHeartbeatSilenceMs: 450,
    sctpSmoothedRttMs: 110,
  });
  assert.equal(backpressureShed.allowed, false);
  assert.equal(backpressureShed.backpressureHealthy, false);
  assert.equal(
    backpressureShed.actionCode,
    "SHED_INTERIM_TRANSCRIPT_FRAMES_COALESCE_STATE_DELTAS_AND_PRIORITIZE_DSCP_EF_SRTP_AUDIO"
  );
  assert.equal(
    backpressureShed.reason,
    "SCTP_BUFFERED_AMOUNT_BACKPRESSURE_OVERFLOW_OR_SRTP_AUDIO_QUEUE_CONTENTION_SHEDDING_TRIGGERED"
  );

  // 3. DTLS-SCTP heartbeat silence > 3000ms -> recycle SCTP stream and failover to WebSocket control plane
  const zombieRecycled = evaluateWebRtcSctpDataChannelBackpressureAndHoLWatchdogGuard({
    sessionId: "call-p110-zombie-03",
    payloadCategory: "CRITICAL_TOOL_STATE",
    dataChannelOrdered: true,
    dataChannelMaxRetransmits: 3,
    bufferedAmountBytes: 8192,
    maxAllowedBufferedAmountBytes: 65536,
    srtpAudioQueueDelayMs: 22,
    sctpHeartbeatSilenceMs: 3600,
    sctpSmoothedRttMs: 1450,
  });
  assert.equal(zombieRecycled.allowed, false);
  assert.equal(zombieRecycled.sctpAssociationHealthy, false);
  assert.equal(
    zombieRecycled.actionCode,
    "RECYCLE_SCTP_STREAM_FAILOVER_TO_WEBSOCKET_CONTROL_PLANE_AND_PRESERVE_SRTP_VOICE"
  );
  assert.equal(
    zombieRecycled.reason,
    "DTLS_SCTP_HEARTBEAT_TIMEOUT_OR_ASSOCIATION_ZOMBIE_STALL_DETECTED"
  );

  // 4. Healthy unordered 0-retransmit interim transcript with low buffer & low SRTP delay -> allow
  const healthyDataChannel = evaluateWebRtcSctpDataChannelBackpressureAndHoLWatchdogGuard({
    sessionId: "call-p110-valid-04",
    payloadCategory: "INTERIM_TRANSCRIPT",
    dataChannelOrdered: false,
    dataChannelMaxRetransmits: 0,
    bufferedAmountBytes: 14336,
    maxAllowedBufferedAmountBytes: 65536,
    srtpAudioQueueDelayMs: 16,
    sctpHeartbeatSilenceMs: 320,
    sctpSmoothedRttMs: 68,
  });
  assert.equal(healthyDataChannel.allowed, true);
  assert.equal(healthyDataChannel.ephemeralReliabilityConfigured, true);
  assert.equal(healthyDataChannel.backpressureHealthy, true);
  assert.equal(healthyDataChannel.sctpAssociationHealthy, true);
  assert.equal(
    healthyDataChannel.actionCode,
    "DISPATCH_SYNCHRONIZED_DATACHANNEL_PAYLOAD"
  );
  assert.equal(
    healthyDataChannel.reason,
    "WEBRTC_SCTP_DATACHANNEL_LOW_LATENCY_AND_SRTP_ISOLATION_HEALTHY"
  );
});

