test("P116 WebRTC RFC 8843 BUNDLE shared 5-tuple negotiation, RFC 5761 rtcp-mux & RFC 8445 ICE-Lite dual-peer deadlock / 487 role conflict guard resolves ICE deadlocks, swaps tie-breaker roles, and enforces BUNDLE rtcp-mux", () => {
  // 1. Both local and remote peers advertise a=ice-lite -> promote gateway to Full ICE Controlling agent in 0ms
  const dualIceLiteBlocked = evaluateWebRtcRfc8843BundleRtcpMuxAndIceLiteRoleConflictGuard({
    sessionId: "webrtc-p116-icelite-01",
    localPeerIsIceLite: true,
    remotePeerIsIceLite: true,
    stun487RoleConflictReceived: false,
    roleSwappedAccordingToTieBreakerUint64: true,
    bundleGroupNegotiated: true,
    duplicateSdpMidAcrossMlines: false,
    rtcpMuxConfirmedOnBundledTransport: true,
  });
  assert.equal(dualIceLiteBlocked.allowed, false);
  assert.equal(dualIceLiteBlocked.iceNominationViable, false);
  assert.equal(
    dualIceLiteBlocked.policyCode,
    "P116-WEBRTC-RFC8843-BUNDLE-RTCP-MUX-AND-RFC8445-ICE-LITE-ROLE-CONFLICT-GUARD"
  );
  assert.equal(
    dualIceLiteBlocked.actionCode,
    "PROMOTE_GATEWAY_TO_FULL_ICE_CONTROLLING_AGENT_AND_INITIATE_STUN_CHECKS"
  );
  assert.equal(
    dualIceLiteBlocked.reason,
    "RFC8445_DUAL_ICE_LITE_PEER_CONNECTIVITY_CHECK_DEADLOCK_DETECTED"
  );

  // 2. STUN 487 Role Conflict received without swapping ICE-CONTROLLED/ICE-CONTROLLING per 64-bit tie-breaker -> swap role and recompute pair priorities
  const roleConflictBlocked = evaluateWebRtcRfc8843BundleRtcpMuxAndIceLiteRoleConflictGuard({
    sessionId: "webrtc-p116-487-02",
    localPeerIsIceLite: false,
    remotePeerIsIceLite: false,
    stun487RoleConflictReceived: true,
    roleSwappedAccordingToTieBreakerUint64: false,
    bundleGroupNegotiated: true,
    duplicateSdpMidAcrossMlines: false,
    rtcpMuxConfirmedOnBundledTransport: true,
  });
  assert.equal(roleConflictBlocked.allowed, false);
  assert.equal(roleConflictBlocked.roleConflictResolved, false);
  assert.equal(
    roleConflictBlocked.actionCode,
    "SWAP_ICE_CONTROLLING_CONTROLLED_ROLE_PER_64BIT_TIEBREAKER_AND_RECOMPUTE_PAIR_PRIORITIES"
  );
  assert.equal(
    roleConflictBlocked.reason,
    "RFC8445_STUN_487_ROLE_CONFLICT_UNRESOLVED_WITHOUT_TIEBREAKER_ROLE_SWAP"
  );

  // 3. Negotiated BUNDLE group has duplicate a=mid across m-lines or lacks a=rtcp-mux -> enforce unique mid and rtcp-mux
  const bundleMuxInvalidBlocked = evaluateWebRtcRfc8843BundleRtcpMuxAndIceLiteRoleConflictGuard({
    sessionId: "webrtc-p116-bundle-03",
    localPeerIsIceLite: false,
    remotePeerIsIceLite: true,
    stun487RoleConflictReceived: false,
    roleSwappedAccordingToTieBreakerUint64: true,
    bundleGroupNegotiated: true,
    duplicateSdpMidAcrossMlines: true,
    rtcpMuxConfirmedOnBundledTransport: false,
  });
  assert.equal(bundleMuxInvalidBlocked.allowed, false);
  assert.equal(bundleMuxInvalidBlocked.bundleRtcpMuxValid, false);
  assert.equal(
    bundleMuxInvalidBlocked.actionCode,
    "ENFORCE_UNIQUE_SDP_MID_AND_RFC5761_RTCP_MUX_ON_BUNDLED_5TUPLE"
  );
  assert.equal(
    bundleMuxInvalidBlocked.reason,
    "RFC8843_BUNDLE_DUPLICATE_MID_OR_MISSING_RTCP_MUX_ON_SHARED_TRANSPORT"
  );

  // 4. Healthy Full ICE + ICE-Lite role negotiation and valid BUNDLE + rtcp-mux -> allow
  const healthyBundle = evaluateWebRtcRfc8843BundleRtcpMuxAndIceLiteRoleConflictGuard({
    sessionId: "webrtc-p116-valid-04",
    localPeerIsIceLite: false,
    remotePeerIsIceLite: true,
    stun487RoleConflictReceived: true,
    roleSwappedAccordingToTieBreakerUint64: true,
    bundleGroupNegotiated: true,
    duplicateSdpMidAcrossMlines: false,
    rtcpMuxConfirmedOnBundledTransport: true,
  });
  assert.equal(healthyBundle.allowed, true);
  assert.equal(healthyBundle.iceNominationViable, true);
  assert.equal(healthyBundle.roleConflictResolved, true);
  assert.equal(healthyBundle.bundleRtcpMuxValid, true);
  assert.equal(
    healthyBundle.actionCode,
    "ESTABLISH_MULTIPLEXED_WEBRTC_MEDIA_TRANSPORT"
  );
  assert.equal(
    healthyBundle.reason,
    "RFC8843_BUNDLE_RTCP_MUX_AND_RFC8445_ICE_ROLE_NEGOTIATION_HEALTHY"
  );
});

