test("P138 WebRTC/RTP RFC 3550 / RFC 3611 RTCP RR / XR report block overflow, DLSR/LSR RTT wrap underflow & spoofed fraction-lost BWE sabotage guard drops truncated RC blocks, discards wrapped RTT samples, and ignores spoofed 100% loss reports", () => {
  // 1. RTCP RR/XR declared report block count RC (e.g. RC=31 -> 744 bytes) exceeds available packet payload -> 0ms drop truncated packet
  const reportBlockOverflowBlocked = evaluateWebrtcRtpRfc3550Rfc3611RtcpXrReportBlockAndRttWrapGuard({
    sessionId: "webrtc-p138-rc-01",
    declaredReportBlockCountRc: 31,
    availablePacketBytesForReportBlocks: 48,
    dlsrPlusLsrExceedsArrivalNtpMiddle32OrFutureLsrDetected: false,
    computedRttMs: 42,
    spoofed100PctFractionLostWithValidSrtpMediaFlowDetected: false,
  });
  assert.equal(reportBlockOverflowBlocked.allowed, false);
  assert.equal(reportBlockOverflowBlocked.rtcpReportBlockCountAndLengthValid, false);
  assert.equal(
    reportBlockOverflowBlocked.policyCode,
    "P138-WEBRTC-RTP-RFC3550-RFC3611-RTCP-XR-RR-REPORT-BLOCK-OVERFLOW-DLSR-RTT-WRAP-UNDERFLOW-AND-SPOOFED-FRACTION-LOST-BWE-SABOTAGE-GUARD"
  );
  assert.equal(
    reportBlockOverflowBlocked.actionCode,
    "DROP_TRUNCATED_RTCP_RR_XR_REPORT_BLOCK_AND_ENFORCE_24BYTE_RC_BOUNDS"
  );
  assert.equal(
    reportBlockOverflowBlocked.reason,
    "RFC3550_RFC3611_RTCP_RR_XR_REPORT_COUNT_OR_BLOCK_LENGTH_EXCEEDS_PACKET_BOUNDS_BLOCKED"
  );

  // 2. DLSR + LSR > arrival NTP middle-32 or negative/wrapped RTT sample -> discard wrapped RTT sample and clamp smoothed RTT
  const rttWrapUnderflowBlocked = evaluateWebrtcRtpRfc3550Rfc3611RtcpXrReportBlockAndRttWrapGuard({
    sessionId: "webrtc-p138-rtt-02",
    declaredReportBlockCountRc: 1,
    availablePacketBytesForReportBlocks: 24,
    dlsrPlusLsrExceedsArrivalNtpMiddle32OrFutureLsrDetected: true,
    computedRttMs: -120,
    spoofed100PctFractionLostWithValidSrtpMediaFlowDetected: false,
  });
  assert.equal(rttWrapUnderflowBlocked.allowed, false);
  assert.equal(rttWrapUnderflowBlocked.lsrDlsrRttCalculationMonotonic, false);
  assert.equal(
    rttWrapUnderflowBlocked.actionCode,
    "DISCARD_WRAPPED_DLSR_LSR_RTT_SAMPLE_AND_CLAMP_SMOOTHED_RTT_ESTIMATE"
  );
  assert.equal(
    rttWrapUnderflowBlocked.reason,
    "RFC3550_RTCP_LSR_DLSR_WALLCLOCK_UNDERFLOW_OR_NEGATIVE_RTT_WRAP_INJECTION_BLOCKED"
  );

  // 3. Spoofed fraction_lost = 255 (100% loss) or R-Factor=0 while SRTP/TWCC media flows normally -> ignore spoofed loss and hold 24 kbps voice floor
  const spoofedFractionLostBlocked = evaluateWebrtcRtpRfc3550Rfc3611RtcpXrReportBlockAndRttWrapGuard({
    sessionId: "webrtc-p138-loss-03",
    declaredReportBlockCountRc: 1,
    availablePacketBytesForReportBlocks: 24,
    dlsrPlusLsrExceedsArrivalNtpMiddle32OrFutureLsrDetected: false,
    computedRttMs: 38,
    spoofed100PctFractionLostWithValidSrtpMediaFlowDetected: true,
  });
  assert.equal(spoofedFractionLostBlocked.allowed, false);
  assert.equal(spoofedFractionLostBlocked.fractionLostAndVoipMetricsAuthentic, false);
  assert.equal(
    spoofedFractionLostBlocked.actionCode,
    "IGNORE_SPOOFED_RTCP_RR_FRACTION_LOST_AND_CROSSCHECK_TWCC_SRTP_COUNTERS"
  );
  assert.equal(
    spoofedFractionLostBlocked.reason,
    "RFC3550_RFC3611_SPOOFED_FRACTION_LOST_OR_VOIP_METRICS_BWE_THROTTLE_SABOTAGE_BLOCKED"
  );

  // 4. Healthy RFC 3550 / RFC 3611 RTCP RR/XR report block with valid 24-byte RC bounds, monotonic RTT, and authentic loss metrics -> allow
  const healthyRtcpRrXr = evaluateWebrtcRtpRfc3550Rfc3611RtcpXrReportBlockAndRttWrapGuard({
    sessionId: "webrtc-p138-valid-04",
    declaredReportBlockCountRc: 2,
    availablePacketBytesForReportBlocks: 48,
    dlsrPlusLsrExceedsArrivalNtpMiddle32OrFutureLsrDetected: false,
    computedRttMs: 34,
    spoofed100PctFractionLostWithValidSrtpMediaFlowDetected: false,
  });
  assert.equal(healthyRtcpRrXr.allowed, true);
  assert.equal(healthyRtcpRrXr.rtcpReportBlockCountAndLengthValid, true);
  assert.equal(healthyRtcpRrXr.lsrDlsrRttCalculationMonotonic, true);
  assert.equal(healthyRtcpRrXr.fractionLostAndVoipMetricsAuthentic, true);
  assert.equal(
    healthyRtcpRrXr.actionCode,
    "ALLOW_VERIFIED_RFC3550_RFC3611_RTCP_RR_XR_TELEMETRY"
  );
  assert.equal(
    healthyRtcpRrXr.reason,
    "WEBRTC_RTP_RFC3550_RFC3611_RTCP_RR_XR_TELEMETRY_HEALTHY"
  );
});

