test("evaluateWebrtcRtpRfc4585Rfc5104AvpfNackPliStormAndRtxOsnGuard enforces RFC 4585/4588/5104 RTCP AVPF NACK/PLI & RTX safety (P144)", () => {
  // 1. NACK bitmask retransmission storm (>250 pkt/s or RTX > 20% media bitrate) -> throttled
  const nackStormBlocked =
    evaluateWebrtcRtpRfc4585Rfc5104AvpfNackPliStormAndRtxOsnGuard({
      streamId: "AVPF-NACK-STORM-901",
      nackRequestedPacketsPerSec: 680,
      rtxRetransmissionBitrateRatio: 0.48,
      rtxAptAndOsnHistoryWindowValid: true,
      rtcpFbIntervalMs: 120,
      negotiatedTrrIntFloorMs: 100,
      pliOrFirRequestsPerSec: 1,
    });
  assert.equal(nackStormBlocked.allowed, false);
  assert.equal(nackStormBlocked.nackRtxBandwidthRatioBounded, false);
  assert.equal(
    nackStormBlocked.actionCode,
    "THROTTLE_RTCP_NACK_BLP_QUEUE_AND_CAP_RTX_EGRESS_AT_20PCT_MEDIA_BW"
  );
  assert.equal(
    nackStormBlocked.reason,
    "RFC4585_RTCP_NACK_BITMASK_RETRANSMISSION_AMPLIFICATION_STORM_BLOCKED"
  );
  assert.equal(
    nackStormBlocked.policyCode,
    "P144-WEBRTC-RTP-RFC4585-RFC5104-RTCP-AVPF-NACK-PLI-FIR-RETRANSMISSION-STORM-RTX-RFC4588-OSN-DESYNC-AND-TRR-INT-THROTTLE-GUARD"
  );

  // 2. RFC 4588 RTX apt or OSN replay window desync -> dropped in 0ms
  const rtxOsnDesyncBlocked =
    evaluateWebrtcRtpRfc4585Rfc5104AvpfNackPliStormAndRtxOsnGuard({
      streamId: "AVPF-RTX-OSN-902",
      nackRequestedPacketsPerSec: 40,
      rtxRetransmissionBitrateRatio: 0.08,
      rtxAptAndOsnHistoryWindowValid: false,
      rtcpFbIntervalMs: 120,
      negotiatedTrrIntFloorMs: 100,
      pliOrFirRequestsPerSec: 1,
    });
  assert.equal(rtxOsnDesyncBlocked.allowed, false);
  assert.equal(rtxOsnDesyncBlocked.rtxAptAndOsnWindowSynced, false);
  assert.equal(
    rtxOsnDesyncBlocked.actionCode,
    "DROP_DESYNCED_RFC4588_RTX_PACKET_AND_ISOLATE_PRIMARY_JITTER_BUFFER"
  );
  assert.equal(
    rtxOsnDesyncBlocked.reason,
    "RFC4588_RTX_ASSOCIATED_PAYLOAD_TYPE_OR_OSN_REPLAY_WINDOW_DESYNC_BLOCKED"
  );

  // 3. RFC 4585 trr-int violation or RFC 5104 PLI/FIR keyframe flood -> throttled & coalesced
  const trrIntPliFloodBlocked =
    evaluateWebrtcRtpRfc4585Rfc5104AvpfNackPliStormAndRtxOsnGuard({
      streamId: "AVPF-PLI-FLOOD-903",
      nackRequestedPacketsPerSec: 30,
      rtxRetransmissionBitrateRatio: 0.06,
      rtxAptAndOsnHistoryWindowValid: true,
      rtcpFbIntervalMs: 15,
      negotiatedTrrIntFloorMs: 100,
      pliOrFirRequestsPerSec: 18,
    });
  assert.equal(trrIntPliFloodBlocked.allowed, false);
  assert.equal(trrIntPliFloodBlocked.trrIntAndPliFirRateRespected, false);
  assert.equal(
    trrIntPliFloodBlocked.actionCode,
    "ENFORCE_RFC4585_TRR_INT_COOLDOWN_AND_COALESCE_PLI_FIR_REQUESTS"
  );
  assert.equal(
    trrIntPliFloodBlocked.reason,
    "RFC4585_RFC5104_TRR_INT_VIOLATION_OR_PLI_FIR_KEYFRAME_FLOOD_BLOCKED"
  );

  // 4. Bounded NACK/RTX ratio, valid apt/OSN window, and compliant trr-int/PLI rate -> allowed
  const healthyAvpfStream =
    evaluateWebrtcRtpRfc4585Rfc5104AvpfNackPliStormAndRtxOsnGuard({
      streamId: "AVPF-HEALTHY-904",
      nackRequestedPacketsPerSec: 24,
      rtxRetransmissionBitrateRatio: 0.05,
      rtxAptAndOsnHistoryWindowValid: true,
      rtcpFbIntervalMs: 120,
      negotiatedTrrIntFloorMs: 100,
      pliOrFirRequestsPerSec: 1,
    });
  assert.equal(healthyAvpfStream.allowed, true);
  assert.equal(healthyAvpfStream.nackRtxBandwidthRatioBounded, true);
  assert.equal(healthyAvpfStream.rtxAptAndOsnWindowSynced, true);
  assert.equal(healthyAvpfStream.trrIntAndPliFirRateRespected, true);
  assert.equal(
    healthyAvpfStream.actionCode,
    "ALLOW_VERIFIED_RTCP_AVPF_FEEDBACK_AND_RFC4588_RTX_RECOVERY"
  );
  assert.equal(
    healthyAvpfStream.reason,
    "WEBRTC_RTP_RFC4585_RFC5104_AVPF_NACK_PLI_AND_RTX_OSN_HEALTHY"
  );
});

