test("evaluateDatacenterTier4Nfpa2001CleanAgentDischargeEpoAndBessThermalRunawayGuard enforces UL 9540A / NFPA 855 BESS thermal runaway, NFPA 2001 clean-agent abort interlock & Tier IV EPO/CDU dual-key safety (P151)", () => {
  // 1. BESS thermal runaway (>=130C or LEL >=10%) while attempting to close DC contactor or enter battery room -> 0ms breaker trip & exhaust interlock
  const bessRunawayBlocked =
    evaluateDatacenterTier4Nfpa2001CleanAgentDischargeEpoAndBessThermalRunawayGuard(
      {
        facilityZoneId: "DC-US-EAST-HALL-4B-BESS-2",
        cleanAgentDischargeCountdownActive: false,
        personnelInWhiteSpaceDuringDischarge: false,
        attemptRemoteBypassPreDischargeAlarmOrAbortSwitch: false,
        voiceRequestsHallWideEpoOrChillerShutdown: false,
        dualOperatorChiefEngineerAndFacilityManagerVerified: true,
        bessThermalRunawayDetected: true,
        bessCellTempCelsius: 142,
        bessOffGasLelPercent: 14,
        attemptCloseBessDcContactorOrSuppressExhaust: true,
        authorizeBatteryRoomEntryDuringRunaway: true,
      }
    );
  assert.equal(bessRunawayBlocked.allowed, false);
  assert.equal(bessRunawayBlocked.bessThermalRunawayContained, false);
  assert.equal(
    bessRunawayBlocked.actionCode,
    "TRIP_BESS_DC_BREAKER_ACTIVATE_DEFLAGRATION_EXHAUST_VENTING_AND_DISPATCH_FIRE_HAZMAT"
  );
  assert.equal(
    bessRunawayBlocked.reason,
    "UL9540A_NFPA855_BESS_THERMAL_RUNAWAY_CONTACTOR_RECLOSE_OR_ROOM_ENTRY_BLOCKED"
  );
  assert.equal(
    bessRunawayBlocked.policyCode,
    "P151-DATA-CENTER-UPTIME-TIER4-NFPA75-76-2001-NOVEC1230-FM200-ABORT-INTERLOCK-EPO-DUAL-CONFIRM-AND-BESS-UL9540A-THERMAL-RUNAWAY-GUARD"
  );

  // 2. NFPA 2001 clean-agent countdown with occupied white space or remote abort bypass -> ABORT_HOLD
  const cleanAgentOccupiedHold =
    evaluateDatacenterTier4Nfpa2001CleanAgentDischargeEpoAndBessThermalRunawayGuard(
      {
        facilityZoneId: "DC-US-EAST-HALL-4B-POD-7",
        cleanAgentDischargeCountdownActive: true,
        personnelInWhiteSpaceDuringDischarge: true,
        attemptRemoteBypassPreDischargeAlarmOrAbortSwitch: true,
        voiceRequestsHallWideEpoOrChillerShutdown: false,
        dualOperatorChiefEngineerAndFacilityManagerVerified: true,
        bessThermalRunawayDetected: false,
        bessCellTempCelsius: 32,
        bessOffGasLelPercent: 0,
        attemptCloseBessDcContactorOrSuppressExhaust: false,
        authorizeBatteryRoomEntryDuringRunaway: false,
      }
    );
  assert.equal(cleanAgentOccupiedHold.allowed, false);
  assert.equal(
    cleanAgentOccupiedHold.nfpa2001CleanAgentDischargeSafe,
    false
  );
  assert.equal(
    cleanAgentOccupiedHold.actionCode,
    "HOLD_NFPA2001_CLEAN_AGENT_RELEASE_ENFORCE_WHITE_SPACE_EGRESS_AND_FORBID_REMOTE_ABORT_BYPASS"
  );
  assert.equal(
    cleanAgentOccupiedHold.reason,
    "NFPA2001_CLEAN_AGENT_DISCHARGE_OCCUPIED_SPACE_OR_REMOTE_ABORT_BYPASS_BLOCKED"
  );

  // 3. Unverified single-operator voice request for hall-wide EPO or 2N CDU cooling shutdown -> blocked
  const unverifiedEpoBlocked =
    evaluateDatacenterTier4Nfpa2001CleanAgentDischargeEpoAndBessThermalRunawayGuard(
      {
        facilityZoneId: "DC-US-EAST-HALL-4B-CDU-LOOP-A",
        cleanAgentDischargeCountdownActive: false,
        personnelInWhiteSpaceDuringDischarge: false,
        attemptRemoteBypassPreDischargeAlarmOrAbortSwitch: false,
        voiceRequestsHallWideEpoOrChillerShutdown: true,
        dualOperatorChiefEngineerAndFacilityManagerVerified: false,
        bessThermalRunawayDetected: false,
        bessCellTempCelsius: 28,
        bessOffGasLelPercent: 0,
        attemptCloseBessDcContactorOrSuppressExhaust: false,
        authorizeBatteryRoomEntryDuringRunaway: false,
      }
    );
  assert.equal(unverifiedEpoBlocked.allowed, false);
  assert.equal(
    unverifiedEpoBlocked.epoAndLiquidCoolingDualAuthVerified,
    false
  );
  assert.equal(
    unverifiedEpoBlocked.actionCode,
    "REQUIRE_DUAL_OPERATOR_CHIEF_ENGINEER_AND_FACILITY_MANAGER_HARDWARE_KEY_FOR_EPO_OR_CDU_SHUTDOWN"
  );
  assert.equal(
    unverifiedEpoBlocked.reason,
    "NFPA75_UPTIME_TIER4_UNVERIFIED_VOICE_EPO_OR_CDU_COOLING_SHUTDOWN_BLOCKED"
  );

  // 4. Healthy Tier IV data center operation
  const healthyDcOp =
    evaluateDatacenterTier4Nfpa2001CleanAgentDischargeEpoAndBessThermalRunawayGuard(
      {
        facilityZoneId: "DC-US-EAST-HALL-4B-POD-1",
        cleanAgentDischargeCountdownActive: false,
        personnelInWhiteSpaceDuringDischarge: false,
        attemptRemoteBypassPreDischargeAlarmOrAbortSwitch: false,
        voiceRequestsHallWideEpoOrChillerShutdown: false,
        dualOperatorChiefEngineerAndFacilityManagerVerified: true,
        bessThermalRunawayDetected: false,
        bessCellTempCelsius: 27,
        bessOffGasLelPercent: 0,
        attemptCloseBessDcContactorOrSuppressExhaust: false,
        authorizeBatteryRoomEntryDuringRunaway: false,
      }
    );
  assert.equal(healthyDcOp.allowed, true);
  assert.equal(
    healthyDcOp.actionCode,
    "ALLOW_VERIFIED_CRITICAL_FACILITY_NOC_OPERATION"
  );
  assert.equal(
    healthyDcOp.reason,
    "DATACENTER_TIER4_NFPA2001_CLEAN_AGENT_EPO_AND_BESS_THERMAL_SAFETY_COMPLIANT"
  );
});

test("evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard enforces RFC 7741/9626 SVC Dependency Descriptor bounds, keyframe upswitch & layer hysteresis (P152)", () => {
  // 1. Dependency Descriptor template count > 64 or out-of-bounds DTI -> 0ms drop
  const descriptorOverflowBlocked =
    evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard(
      {
        sessionId: "webrtc-svc-sess-01",
        codecType: "AV1-SVC",
        dependencyTemplateCount: 78,
        decodeTargetLayerIndexOutOfBounds: true,
        extensionPayloadBytesExceedRemainingHeader: true,
        currentSpatialLayerId: 1,
        targetSpatialLayerId: 1,
        upswitchOnNonKeyframeWithoutIntraRefresh: false,
        interLayerReferenceBaseDroppedWhileDFlagSet: false,
        spatialLayerSwitchesIn2SecWindow: 0,
      }
    );
  assert.equal(descriptorOverflowBlocked.allowed, false);
  assert.equal(descriptorOverflowBlocked.dependencyDescriptorHeaderSafe, false);
  assert.equal(
    descriptorOverflowBlocked.actionCode,
    "DROP_MALFORMED_RTP_SVC_DEPENDENCY_DESCRIPTOR_PACKET_AND_PRESERVE_SFU_PARSER"
  );
  assert.equal(
    descriptorOverflowBlocked.reason,
    "RFC9626_AV1_SVC_DEPENDENCY_DESCRIPTOR_TEMPLATE_OR_DECODE_TARGET_OVERFLOW_BLOCKED"
  );
  assert.equal(
    descriptorOverflowBlocked.policyCode,
    "P152-WEBRTC-RTP-RFC7741-RFC9626-SVC-VP9-AV1-SPATIAL-TEMPORAL-LAYER-DEPENDENCY-DESCRIPTOR-OVERFLOW-MISSING-KEYFRAME-DISCARD-AND-BITRATE-THRASH-GUARD"
  );

  // 2. Spatial upswitch (S0 -> S2) on non-keyframe or broken base layer with D=1 -> hold S0 and request PLI
  const nonKeyframeUpswitchBlocked =
    evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard(
      {
        sessionId: "webrtc-svc-sess-02",
        codecType: "VP9-SVC",
        dependencyTemplateCount: 12,
        decodeTargetLayerIndexOutOfBounds: false,
        extensionPayloadBytesExceedRemainingHeader: false,
        currentSpatialLayerId: 0,
        targetSpatialLayerId: 2,
        upswitchOnNonKeyframeWithoutIntraRefresh: true,
        interLayerReferenceBaseDroppedWhileDFlagSet: true,
        spatialLayerSwitchesIn2SecWindow: 1,
      }
    );
  assert.equal(nonKeyframeUpswitchBlocked.allowed, false);
  assert.equal(
    nonKeyframeUpswitchBlocked.spatialLayerChainDecodable,
    false
  );
  assert.equal(
    nonKeyframeUpswitchBlocked.actionCode,
    "HOLD_CURRENT_DEC0DABLE_SPATIAL_LAYER_DROP_BROKEN_UPPER_LAYER_AND_SEND_RTCP_PLI"
  );
  assert.equal(
    nonKeyframeUpswitchBlocked.reason,
    "RFC7741_RFC9628_SVC_SPATIAL_UPSWITCH_WITHOUT_KEYFRAME_OR_BROKEN_BASE_LAYER_BLOCKED"
  );

  // 3. Rapid spatial layer oscillation (>3 switches in 2s window) -> hysteresis clamp to temporal scaling
  const oscillationClamped =
    evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard(
      {
        sessionId: "webrtc-svc-sess-03",
        codecType: "AV1-SVC",
        dependencyTemplateCount: 16,
        decodeTargetLayerIndexOutOfBounds: false,
        extensionPayloadBytesExceedRemainingHeader: false,
        currentSpatialLayerId: 1,
        targetSpatialLayerId: 2,
        upswitchOnNonKeyframeWithoutIntraRefresh: false,
        interLayerReferenceBaseDroppedWhileDFlagSet: false,
        spatialLayerSwitchesIn2SecWindow: 6,
      }
    );
  assert.equal(oscillationClamped.allowed, false);
  assert.equal(oscillationClamped.bitrateAdaptationStable, false);
  assert.equal(
    oscillationClamped.actionCode,
    "CLAMP_TO_LOWER_STABLE_SPATIAL_LAYER_AND_ENFORCE_2S_UPSWITCH_HYSTERESIS"
  );
  assert.equal(
    oscillationClamped.reason,
    "SVC_SPATIAL_LAYER_HYSTERESIS_CLAMP_ON_RAPID_BWE_OSCILLATION_APPLIED"
  );

  // 4. Clean keyframe-aligned SVC forwarding
  const healthySvcForwarding =
    evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard(
      {
        sessionId: "webrtc-svc-sess-04",
        codecType: "AV1-SVC",
        dependencyTemplateCount: 16,
        decodeTargetLayerIndexOutOfBounds: false,
        extensionPayloadBytesExceedRemainingHeader: false,
        currentSpatialLayerId: 1,
        targetSpatialLayerId: 2,
        upswitchOnNonKeyframeWithoutIntraRefresh: false,
        interLayerReferenceBaseDroppedWhileDFlagSet: false,
        spatialLayerSwitchesIn2SecWindow: 1,
      }
    );
  assert.equal(healthySvcForwarding.allowed, true);
  assert.equal(
    healthySvcForwarding.actionCode,
    "FORWARD_SVC_SPATIAL_TEMPORAL_LAYER_PACKET"
  );
  assert.equal(
    healthySvcForwarding.reason,
    "WEBRTC_RFC7741_RFC9628_RFC9626_SVC_DEPENDENCY_DESCRIPTOR_AND_LAYER_SWITCH_HEALTHY"
  );
});

