test("evaluateWebrtcSrtpRfc3711Rfc7714Rfc5764RocRolloverDesyncReplayWindowExhaustionAesGcmNonceReuseAndUnencryptedSrtcpBypassGuard blocks AES-GCM nonce reuse & 2^48/2^31 key overflow, ROC/replay-window pre-MAC poisoning, and unauthenticated SRTCP (P180)", () => {
  // 1. Duplicate (SSRC, ROC, SEQ) IV under same master key or SRTP > 2^48 / SRTCP > 2^31 lifetime overflow -> invalidate context & force DTLS-SRTP rekey
  const nonceReuseOrOverflowBlocked =
    evaluateWebrtcSrtpRfc3711Rfc7714Rfc5764RocRolloverDesyncReplayWindowExhaustionAesGcmNonceReuseAndUnencryptedSrtcpBypassGuard({
      duplicateSsrcRocSeqWithSameMasterKeyDetected: true,
      srtpPacketIndexExceeds2Pow48OrSrtcpExceeds2Pow31: true,
      unauthenticatedPacketMutatesRocOrReplayWindowBeforeMacVerify: false,
      packetFallsBehindSrtpReplayWindowOrDuplicateBitSet: false,
      srtcpAuthenticationDisabledOrMissingEbitTag: false,
    });
  assert.equal(nonceReuseOrOverflowBlocked.allowed, false);
  assert.equal(nonceReuseOrOverflowBlocked.aesGcmNonceReuseOrKeyLifetimeOverflowBlocked, true);
  assert.equal(
    nonceReuseOrOverflowBlocked.policyCode,
    "P180-WEBRTC-SRTP-RFC3711-RFC7714-RFC5764-ROC-ROLLOVER-DESYNC-REPLAY-WINDOW-EXHAUSTION-AES-GCM-NONCE-REUSE-AND-UNENCRYPTED-SRTCP-BYPASS-GUARD"
  );
  assert.equal(
    nonceReuseOrOverflowBlocked.actionCode,
    "INVALIDATE_SRTP_CONTEXT_AND_FORCE_DTLS_SRTP_REKEY_ON_NONCE_COLLISION_OR_KEY_LIFETIME_EXHAUSTION"
  );
  assert.equal(
    nonceReuseOrOverflowBlocked.reason,
    "RFC3711_RFC7714_SRTP_AES_GCM_IV_NONCE_REUSE_TWO_TIME_PAD_OR_2POW48_KEY_LIFETIME_OVERFLOW_BLOCKED"
  );

  // 2. Unauthenticated packet mutating estimated v/ROC or 128-bit replay bitmap before MAC verify, or replay window hit -> drop & freeze ROC/bitmap
  const rocOrReplayPoisoningBlocked =
    evaluateWebrtcSrtpRfc3711Rfc7714Rfc5764RocRolloverDesyncReplayWindowExhaustionAesGcmNonceReuseAndUnencryptedSrtcpBypassGuard({
      duplicateSsrcRocSeqWithSameMasterKeyDetected: false,
      srtpPacketIndexExceeds2Pow48OrSrtcpExceeds2Pow31: false,
      unauthenticatedPacketMutatesRocOrReplayWindowBeforeMacVerify: true,
      packetFallsBehindSrtpReplayWindowOrDuplicateBitSet: true,
      srtcpAuthenticationDisabledOrMissingEbitTag: false,
    });
  assert.equal(rocOrReplayPoisoningBlocked.allowed, false);
  assert.equal(rocOrReplayPoisoningBlocked.rocDesyncOrReplayWindowJumpDropped, true);
  assert.equal(
    rocOrReplayPoisoningBlocked.actionCode,
    "DROP_SRTP_PACKET_BEFORE_ROC_OR_REPLAY_BITMAP_MUTATION_AND_ENFORCE_AUTHENTICATE_FIRST"
  );
  assert.equal(
    rocOrReplayPoisoningBlocked.reason,
    "RFC3711_SECTION_3_3_UNAUTHENTICATED_ROC_DESYNC_POISONING_OR_SRTP_REPLAY_WINDOW_HIT_BLOCKED"
  );

  // 3. SRTCP authentication disabled (UNAUTHENTICATED_SRTCP) or missing E-bit / SRTCP index / auth tag -> reject control packet
  const unauthenticatedSrtcpBlocked =
    evaluateWebrtcSrtpRfc3711Rfc7714Rfc5764RocRolloverDesyncReplayWindowExhaustionAesGcmNonceReuseAndUnencryptedSrtcpBypassGuard({
      duplicateSsrcRocSeqWithSameMasterKeyDetected: false,
      srtpPacketIndexExceeds2Pow48OrSrtcpExceeds2Pow31: false,
      unauthenticatedPacketMutatesRocOrReplayWindowBeforeMacVerify: false,
      packetFallsBehindSrtpReplayWindowOrDuplicateBitSet: false,
      srtcpAuthenticationDisabledOrMissingEbitTag: true,
    });
  assert.equal(unauthenticatedSrtcpBlocked.allowed, false);
  assert.equal(unauthenticatedSrtcpBlocked.unauthenticatedSrtcpControlDowngradeBlocked, true);
  assert.equal(
    unauthenticatedSrtcpBlocked.actionCode,
    "REJECT_UNAUTHENTICATED_SRTCP_PROFILE_AND_MANDATE_RFC3711_SRTCP_HMAC_AEAD_TAG"
  );
  assert.equal(
    unauthenticatedSrtcpBlocked.reason,
    "RFC3711_SECTION_3_4_MANDATORY_SRTCP_AUTHENTICATION_BYPASS_OR_MISSING_SRTCP_TAG_BLOCKED"
  );

  // 4. Compliant WebRTC SRTP / SRTCP RFC 3711 / RFC 7714 packet processing
  const compliantWebrtcSrtpPacket =
    evaluateWebrtcSrtpRfc3711Rfc7714Rfc5764RocRolloverDesyncReplayWindowExhaustionAesGcmNonceReuseAndUnencryptedSrtcpBypassGuard({
      duplicateSsrcRocSeqWithSameMasterKeyDetected: false,
      srtpPacketIndexExceeds2Pow48OrSrtcpExceeds2Pow31: false,
      unauthenticatedPacketMutatesRocOrReplayWindowBeforeMacVerify: false,
      packetFallsBehindSrtpReplayWindowOrDuplicateBitSet: false,
      srtcpAuthenticationDisabledOrMissingEbitTag: false,
    });
  assert.equal(compliantWebrtcSrtpPacket.allowed, true);
  assert.equal(
    compliantWebrtcSrtpPacket.actionCode,
    "ALLOW_VERIFIED_SRTP_AND_SRTCP_ENCRYPTED_MEDIA_PACKET"
  );
  assert.equal(
    compliantWebrtcSrtpPacket.reason,
    "WEBRTC_SRTP_RFC3711_RFC7714_ROC_REPLAY_WINDOW_AES_GCM_IV_AND_SRTCP_AUTH_VERIFIED"
  );
});

