test("evaluateSipRfc3261Rfc5626Rfc5923RecordRouteLooseRoutingLoopOpenRelayMaxForwardsExhaustionAndTlsTransportDowngradeGuard blocks preloaded Route open-relay/;lr loops, Max-Forwards 0/>70 spirals, and SIPS/TLS transport downgrade (P182)", () => {
  // 1. Preloaded external Route open-relay reflection or missing ;lr loose-routing parameter -> SIP 403/482 rejection
  const openRelayOrStrictRoutingBlocked =
    evaluateSipRfc3261Rfc5626Rfc5923RecordRouteLooseRoutingLoopOpenRelayMaxForwardsExhaustionAndTlsTransportDowngradeGuard({
      preloadedExternalRouteOrMissingLooseRoutingLrParamDetected: true,
      incomingMaxForwardsValue: 70,
      isForwardedRequestOrSpiralSuspected: true,
      sipsOrTlsDialogRouteDowngradesToCleartextOrFailsMtlsSan: false,
    });
  assert.equal(openRelayOrStrictRoutingBlocked.allowed, false);
  assert.equal(openRelayOrStrictRoutingBlocked.recordRouteOpenRelayOrStrictRoutingLoopRejected, true);
  assert.equal(
    openRelayOrStrictRoutingBlocked.policyCode,
    "P182-SIP-RFC3261-RFC5626-RFC5923-RECORD-ROUTE-LOOSE-ROUTING-LOOP-OPEN-RELAY-MAX-FORWARDS-EXHAUSTION-AND-TLS-TRANSPORT-DOWNGRADE-GUARD"
  );
  assert.equal(
    openRelayOrStrictRoutingBlocked.actionCode,
    "REJECT_SIP_403_OR_482_ON_PRELOADED_EXTERNAL_ROUTE_OPEN_RELAY_OR_STRICT_ROUTING_LOOP"
  );
  assert.equal(
    openRelayOrStrictRoutingBlocked.reason,
    "RFC3261_SECTION_16_4_PRELOADED_ROUTE_OPEN_RELAY_REFLECTION_OR_STRICT_ROUTING_LOOP_BLOCKED"
  );

  // 2. Max-Forwards <= 0 exhaustion or > 70 proxy-spiral amplification -> SIP 483 Too Many Hops
  const maxForwardsSpiralBlocked =
    evaluateSipRfc3261Rfc5626Rfc5923RecordRouteLooseRoutingLoopOpenRelayMaxForwardsExhaustionAndTlsTransportDowngradeGuard({
      preloadedExternalRouteOrMissingLooseRoutingLrParamDetected: false,
      incomingMaxForwardsValue: 254,
      isForwardedRequestOrSpiralSuspected: true,
      sipsOrTlsDialogRouteDowngradesToCleartextOrFailsMtlsSan: false,
    });
  assert.equal(maxForwardsSpiralBlocked.allowed, false);
  assert.equal(maxForwardsSpiralBlocked.maxForwardsExhaustedOrSpiralAmplificationBlocked483, true);
  assert.equal(
    maxForwardsSpiralBlocked.actionCode,
    "REJECT_SIP_483_TOO_MANY_HOPS_OR_CLAMP_ABNORMAL_MAX_FORWARDS_SPIRAL"
  );
  assert.equal(
    maxForwardsSpiralBlocked.reason,
    "RFC3261_SECTION_16_3_MAX_FORWARDS_ZERO_EXHAUSTION_OR_SPIRAL_AMPLIFICATION_BLOCKED"
  );

  // 3. SIPS / TLS Record-Route or Contact transport downgrade to cleartext UDP/TCP -> SIP 416/403 rejection
  const tlsRouteDowngradeBlocked =
    evaluateSipRfc3261Rfc5626Rfc5923RecordRouteLooseRoutingLoopOpenRelayMaxForwardsExhaustionAndTlsTransportDowngradeGuard({
      preloadedExternalRouteOrMissingLooseRoutingLrParamDetected: false,
      incomingMaxForwardsValue: 68,
      isForwardedRequestOrSpiralSuspected: true,
      sipsOrTlsDialogRouteDowngradesToCleartextOrFailsMtlsSan: true,
    });
  assert.equal(tlsRouteDowngradeBlocked.allowed, false);
  assert.equal(tlsRouteDowngradeBlocked.sipsOrTlsRouteTransportDowngradeBlocked, true);
  assert.equal(
    tlsRouteDowngradeBlocked.actionCode,
    "REJECT_SIP_416_OR_403_ON_SIPS_TLS_TO_CLEARTEXT_UDP_TCP_ROUTE_DOWNGRADE"
  );
  assert.equal(
    tlsRouteDowngradeBlocked.reason,
    "RFC5923_RFC3261_SECTION_26_SIPS_OR_TLS_RECORD_ROUTE_CLEARTEXT_DOWNGRADE_BLOCKED"
  );

  // 4. Compliant SIP loose-routed TLS dialog request
  const compliantSipRouteRequest =
    evaluateSipRfc3261Rfc5626Rfc5923RecordRouteLooseRoutingLoopOpenRelayMaxForwardsExhaustionAndTlsTransportDowngradeGuard({
      preloadedExternalRouteOrMissingLooseRoutingLrParamDetected: false,
      incomingMaxForwardsValue: 68,
      isForwardedRequestOrSpiralSuspected: true,
      sipsOrTlsDialogRouteDowngradesToCleartextOrFailsMtlsSan: false,
    });
  assert.equal(compliantSipRouteRequest.allowed, true);
  assert.equal(
    compliantSipRouteRequest.actionCode,
    "ALLOW_VERIFIED_SIP_LOOSE_ROUTED_TLS_DIALOG_REQUEST"
  );
  assert.equal(
    compliantSipRouteRequest.reason,
    "SIP_RFC3261_RFC5626_RFC5923_LOOSE_ROUTING_MAX_FORWARDS_AND_TLS_ROUTE_SET_VERIFIED"
  );
});

