test("evaluateWebrtcSctpDataChannelRfc8831Rfc8832Rfc4960VerificationTagMismatchDcepStreamIdParityCollisionAndMaxMessageSizeBombGuard blocks SCTP Verification Tag mismatch, DCEP Stream ID parity collision, and max-message-size bomb (P184)", () => {
  // 1. SCTP Verification Tag mismatch or chunk not bound to active DTLS session -> silent packet drop
  const sctpVtagDropped =
    evaluateWebrtcSctpDataChannelRfc8831Rfc8832Rfc4960VerificationTagMismatchDcepStreamIdParityCollisionAndMaxMessageSizeBombGuard({
      sctpVerificationTagMatchesAssociationAndBoundToDtls: false,
      dcepStreamIdParityViolationOrActiveStreamCollisionDetected: false,
      cumulativeSctpMessagePayloadBytes: 2048,
      negotiatedSdpMaxMessageSizeBytes: 65536,
      unboundedFragmentReassemblyQueueDetected: false,
    });
  assert.equal(sctpVtagDropped.allowed, false);
  assert.equal(sctpVtagDropped.sctpVerificationTagMismatchOrDtlsUnboundChunkDropped, true);
  assert.equal(
    sctpVtagDropped.policyCode,
    "P184-WEBRTC-SCTP-DATACHANNEL-RFC8831-RFC8832-RFC4960-VERIFICATION-TAG-MISMATCH-DCEP-STREAM-ID-PARITY-COLLISION-AND-MAX-MESSAGE-SIZE-BOMB-GUARD"
  );
  assert.equal(
    sctpVtagDropped.actionCode,
    "DROP_SCTP_CHUNK_WITH_MISMATCHED_VERIFICATION_TAG_OR_UNBOUND_DTLS_ASSOCIATION_0MS"
  );
  assert.equal(
    sctpVtagDropped.reason,
    "RFC4960_SECTION_8_5_SCTP_VERIFICATION_TAG_MISMATCH_OR_UNBOUND_DTLS_CONTROL_CHUNK_DROPPED"
  );

  // 2. DCEP Stream ID DTLS client-even/server-odd parity violation or active Stream ID collision -> reject DCEP open & reset stream
  const dcepParityOrCollisionBlocked =
    evaluateWebrtcSctpDataChannelRfc8831Rfc8832Rfc4960VerificationTagMismatchDcepStreamIdParityCollisionAndMaxMessageSizeBombGuard({
      sctpVerificationTagMatchesAssociationAndBoundToDtls: true,
      dcepStreamIdParityViolationOrActiveStreamCollisionDetected: true,
      cumulativeSctpMessagePayloadBytes: 2048,
      negotiatedSdpMaxMessageSizeBytes: 65536,
      unboundedFragmentReassemblyQueueDetected: false,
    });
  assert.equal(dcepParityOrCollisionBlocked.allowed, false);
  assert.equal(dcepParityOrCollisionBlocked.dcepStreamIdParityCollisionOrOpenFloodRejected, true);
  assert.equal(
    dcepParityOrCollisionBlocked.actionCode,
    "REJECT_DCEP_DATA_CHANNEL_OPEN_ON_DTLS_ROLE_PARITY_VIOLATION_OR_ACTIVE_STREAM_COLLISION"
  );
  assert.equal(
    dcepParityOrCollisionBlocked.reason,
    "RFC8832_SECTION_6_DCEP_STREAM_ID_ODD_EVEN_PARITY_COLLISION_OR_OPEN_FLOOD_BLOCKED"
  );

  // 3. Cumulative SCTP message payload > negotiated max-message-size (65,536 bytes) or unbounded fragment reassembly bomb -> abort reassembly & close channel
  const sctpMessageSizeBombBlocked =
    evaluateWebrtcSctpDataChannelRfc8831Rfc8832Rfc4960VerificationTagMismatchDcepStreamIdParityCollisionAndMaxMessageSizeBombGuard({
      sctpVerificationTagMatchesAssociationAndBoundToDtls: true,
      dcepStreamIdParityViolationOrActiveStreamCollisionDetected: false,
      cumulativeSctpMessagePayloadBytes: 262144,
      negotiatedSdpMaxMessageSizeBytes: 65536,
      unboundedFragmentReassemblyQueueDetected: true,
    });
  assert.equal(sctpMessageSizeBombBlocked.allowed, false);
  assert.equal(sctpMessageSizeBombBlocked.sctpMaxMessageSizeOrFragmentReassemblyBombBlocked, true);
  assert.equal(
    sctpMessageSizeBombBlocked.actionCode,
    "ABORT_SCTP_STREAM_REASSEMBLY_AND_ENFORCE_SDP_MAX_MESSAGE_SIZE_CAP"
  );
  assert.equal(
    sctpMessageSizeBombBlocked.reason,
    "RFC8841_RFC8831_SCTP_MAX_MESSAGE_SIZE_EXCEEDED_OR_FRAGMENT_REASSEMBLY_BOMB_BLOCKED"
  );

  // 4. Compliant WebRTC SCTP DataChannel frame
  const compliantDataChannelFrame =
    evaluateWebrtcSctpDataChannelRfc8831Rfc8832Rfc4960VerificationTagMismatchDcepStreamIdParityCollisionAndMaxMessageSizeBombGuard({
      sctpVerificationTagMatchesAssociationAndBoundToDtls: true,
      dcepStreamIdParityViolationOrActiveStreamCollisionDetected: false,
      cumulativeSctpMessagePayloadBytes: 2048,
      negotiatedSdpMaxMessageSizeBytes: 65536,
      unboundedFragmentReassemblyQueueDetected: false,
    });
  assert.equal(compliantDataChannelFrame.allowed, true);
  assert.equal(
    compliantDataChannelFrame.actionCode,
    "ALLOW_VERIFIED_WEBRTC_SCTP_DATACHANNEL_FRAME"
  );
  assert.equal(
    compliantDataChannelFrame.reason,
    "WEBRTC_SCTP_DATACHANNEL_RFC8831_RFC8832_RFC4960_VTAG_DCEP_PARITY_AND_MESSAGE_SIZE_VERIFIED"
  );
});

