  assert.equal(
    spherePolymerizationInterlock.reason,
    "API_RP_521_OSHA_1910_119_EO_PO_STORAGE_SPHERE_POLYMERIZATION_RUNAWAY_OR_CONTAMINATION_INTERLOCK"
  );

  // 3. Ambient EO >= 1.0 ppm or unloading bay / canned-pump LOTO unverified -> unloading valve & canned pump locked
