test("evaluateWebrtcIceRfc8445Rfc6544Rfc4571TcpFramingLengthDesyncUseCandidateNominationThrashAndXorMappedLoopbackGuard blocks RFC 4571 16-bit TCP framing length desync, controlled-peer USE-CANDIDATE nomination thrash, and spoofed XOR-MAPPED-ADDRESS loopback hijack (P192)", () => {
  // 1. RFC 4571 16-bit TCP framing length > 16,384 bytes, length-prefix desync, or HOL queue stall > 250ms -> abort ICE-TCP socket
  const tcpFramingDesyncBlocked =
    evaluateWebrtcIceRfc8445Rfc6544Rfc4571TcpFramingLengthDesyncUseCandidateNominationThrashAndXorMappedLoopbackGuard({
      rfc4571DeclaredFrameLengthBytes: 65535,
      maxAllowedRfc4571FrameBytes: 16384,
      rfc4571LengthPrefixDesyncDetected: true,
      tcpSendBufferQueueMs: 420,
      maxAllowedTcpSendQueueMs: 250,
      remoteControlledPeerSentUseCandidate: false,
      candidateNominationSwitchesPerSec: 1,
      maxAllowedNominationSwitchesPerSec: 3,
      stun96BitTransactionIdMatchedPendingRequest: true,
      xorMappedAddressSelfLoopbackOrLinkLocalDetected: false,
    });
  assert.equal(tcpFramingDesyncBlocked.allowed, false);
  assert.equal(
    tcpFramingDesyncBlocked.rfc4571IceTcpFramingDesyncOrHolStallBlocked,
    true
  );
  assert.equal(
    tcpFramingDesyncBlocked.policyCode,
    "P192-WEBRTC-ICE-RFC8445-RFC6544-RFC4571-TCP-FRAMING-LENGTH-DESYNC-USE-CANDIDATE-NOMINATION-THRASH-AND-XOR-MAPPED-LOOPBACK-GUARD"
  );
  assert.equal(
    tcpFramingDesyncBlocked.actionCode,
    "ABORT_DESYNCED_RFC4571_ICE_TCP_SOCKET_AND_FAILOVER_TO_VERIFIED_CANDIDATE_PAIR"
  );
  assert.equal(
    tcpFramingDesyncBlocked.reason,
    "RFC6544_RFC4571_ICE_TCP_16BIT_LENGTH_FRAMING_DESYNC_OR_HOL_QUEUE_STALL_BLOCKED"
  );

  // 2. Controlled peer sent USE-CANDIDATE or nomination switches > 3/s -> pin selected ICE candidate pair
  const nominationThrashPinned =
    evaluateWebrtcIceRfc8445Rfc6544Rfc4571TcpFramingLengthDesyncUseCandidateNominationThrashAndXorMappedLoopbackGuard({
      rfc4571DeclaredFrameLengthBytes: 160,
      maxAllowedRfc4571FrameBytes: 16384,
      rfc4571LengthPrefixDesyncDetected: false,
      tcpSendBufferQueueMs: 25,
      maxAllowedTcpSendQueueMs: 250,
      remoteControlledPeerSentUseCandidate: true,
      candidateNominationSwitchesPerSec: 18,
      maxAllowedNominationSwitchesPerSec: 3,
      stun96BitTransactionIdMatchedPendingRequest: true,
      xorMappedAddressSelfLoopbackOrLinkLocalDetected: false,
    });
  assert.equal(nominationThrashPinned.allowed, false);
  assert.equal(
    nominationThrashPinned.controlledPeerUseCandidateOrNominationThrashBlocked,
    true
  );
  assert.equal(
    nominationThrashPinned.actionCode,
    "IGNORE_CONTROLLED_PEER_USE_CANDIDATE_AND_PIN_SELECTED_ICE_CANDIDATE_PAIR"
  );
  assert.equal(
    nominationThrashPinned.reason,
    "RFC8445_SECTION_7_3_1_5_CONTROLLED_PEER_USE_CANDIDATE_VIOLATION_OR_NOMINATION_THRASH_BLOCKED"
  );

  // 3. STUN 96-bit transaction ID mismatch or spoofed XOR-MAPPED-ADDRESS self-loopback / link-local -> dropped
  const spoofedXorMappedDropped =
    evaluateWebrtcIceRfc8445Rfc6544Rfc4571TcpFramingLengthDesyncUseCandidateNominationThrashAndXorMappedLoopbackGuard({
      rfc4571DeclaredFrameLengthBytes: 160,
      maxAllowedRfc4571FrameBytes: 16384,
      rfc4571LengthPrefixDesyncDetected: false,
      tcpSendBufferQueueMs: 25,
      maxAllowedTcpSendQueueMs: 250,
      remoteControlledPeerSentUseCandidate: false,
      candidateNominationSwitchesPerSec: 1,
      maxAllowedNominationSwitchesPerSec: 3,
      stun96BitTransactionIdMatchedPendingRequest: false,
      xorMappedAddressSelfLoopbackOrLinkLocalDetected: true,
    });
  assert.equal(spoofedXorMappedDropped.allowed, false);
  assert.equal(
    spoofedXorMappedDropped.stunTransactionMismatchOrXorMappedLoopbackBlocked,
    true
  );
  assert.equal(
    spoofedXorMappedDropped.actionCode,
    "DROP_UNMATCHED_STUN_RESPONSE_AND_REJECT_LOOPBACK_XOR_MAPPED_ADDRESS"
  );
  assert.equal(
    spoofedXorMappedDropped.reason,
    "RFC5389_STUN_96BIT_TRANSACTION_ID_MISMATCH_OR_XOR_MAPPED_SELF_LOOPBACK_HIJACK_BLOCKED"
  );

  // 4. Compliant ICE-TCP / STUN candidate pair
  const compliantIcePair =
    evaluateWebrtcIceRfc8445Rfc6544Rfc4571TcpFramingLengthDesyncUseCandidateNominationThrashAndXorMappedLoopbackGuard({
      rfc4571DeclaredFrameLengthBytes: 160,
      maxAllowedRfc4571FrameBytes: 16384,
      rfc4571LengthPrefixDesyncDetected: false,
      tcpSendBufferQueueMs: 25,
      maxAllowedTcpSendQueueMs: 250,
      remoteControlledPeerSentUseCandidate: false,
      candidateNominationSwitchesPerSec: 1,
      maxAllowedNominationSwitchesPerSec: 3,
      stun96BitTransactionIdMatchedPendingRequest: true,
      xorMappedAddressSelfLoopbackOrLinkLocalDetected: false,
    });
  assert.equal(compliantIcePair.allowed, true);
  assert.equal(
    compliantIcePair.actionCode,
    "ALLOW_VERIFIED_ICE_TCP_AND_STUN_NOMINATION_TRANSPORT"
  );
  assert.equal(
    compliantIcePair.reason,
    "WEBRTC_ICE_RFC8445_RFC6544_RFC4571_FRAMING_NOMINATION_AND_XOR_MAPPED_ADDRESS_VERIFIED"
  );
});

