test("evaluateSipRfc3261Rfc3581SingletonHeaderSmugglingUntrusted3xxRedirectTollFraudSsrfAndViaRportAmplificationGuard rejects duplicate SIP singleton headers / Content-Length smuggling, blocks untrusted 3xx Contact redirect loops & SSRF/toll-fraud, and pins Via received/rport (P194)", () => {
  // 1. Duplicate From/To/Call-ID/CSeq singleton header (count != 4) or Content-Length body smuggling -> reject with SIP 410 Bad Request
  const singletonSmugglingBlocked =
    evaluateSipRfc3261Rfc3581SingletonHeaderSmugglingUntrusted3xxRedirectTollFraudSsrfAndViaRportAmplificationGuard({
      singletonHeaderCountFromToCallIdCseq: 5,
      declaredContentLengthBytes: 180,
      actualSipBodyByteLength: 640,
      sip3xxRedirectHopCount: 0,
      maxAllowed3xxRedirectHops: 2,
      redirectContactTargetInUntrustedTollOrPrivateSubnet: false,
      topmostViaSentByMatchesSourceIpPort: true,
      rfc3581ReceivedAndRportPinnedToTransportTuple: true,
    });
  assert.equal(singletonSmugglingBlocked.allowed, false);
  assert.equal(
    singletonSmugglingBlocked.singletonHeaderSmugglingOrContentLengthMismatchRejected,
    true
  );
  assert.equal(
    singletonSmugglingBlocked.policyCode,
    "P194-SIP-RFC3261-RFC3581-SINGLETON-HEADER-SMUGGLING-UNTRUSTED-3XX-REDIRECT-TOLL-FRAUD-SSRF-AND-VIA-RPORT-AMPLIFICATION-GUARD"
  );
  assert.equal(
    singletonSmugglingBlocked.actionCode,
    "REJECT_SMUGGLED_SIP_MESSAGE_WITH_400_BAD_REQUEST_AND_DROP_BODY_DESYNC"
  );
  assert.equal(
    singletonSmugglingBlocked.reason,
    "RFC3261_SECTION_8_1_1_SINGLETON_HEADER_SMUGGLING_OR_CONTENT_LENGTH_FRAMING_MISMATCH_BLOCKED"
  );

  // 2. 3xx Contact redirect hop count > 2 or target in untrusted international toll / RFC 1918 private subnet -> block redirect recursion
  const untrusted3xxRedirectBlocked =
    evaluateSipRfc3261Rfc3581SingletonHeaderSmugglingUntrusted3xxRedirectTollFraudSsrfAndViaRportAmplificationGuard({
      singletonHeaderCountFromToCallIdCseq: 4,
      declaredContentLengthBytes: 240,
      actualSipBodyByteLength: 240,
      sip3xxRedirectHopCount: 4,
      maxAllowed3xxRedirectHops: 2,
      redirectContactTargetInUntrustedTollOrPrivateSubnet: true,
      topmostViaSentByMatchesSourceIpPort: true,
      rfc3581ReceivedAndRportPinnedToTransportTuple: true,
    });
  assert.equal(untrusted3xxRedirectBlocked.allowed, false);
  assert.equal(
    untrusted3xxRedirectBlocked.untrusted3xxRedirectTollFraudOrSsrfBlocked,
    true
  );
  assert.equal(
    untrusted3xxRedirectBlocked.actionCode,
    "BLOCK_UNTRUSTED_3XX_CONTACT_REDIRECT_AND_ENFORCE_TRUNK_ALLOWLIST"
  );
  assert.equal(
    untrusted3xxRedirectBlocked.reason,
    "RFC3261_SECTION_8_1_3_4_UNTRUSTED_3XX_CONTACT_REDIRECT_TOLL_FRAUD_OR_PRIVATE_SSRF_BLOCKED"
  );

  // 3. Topmost Via sent-by spoofing without RFC 3581 received/rport pinned to actual L4 transport tuple -> rewrite and pin to source IP:port
  const viaRportReflectionPinned =
    evaluateSipRfc3261Rfc3581SingletonHeaderSmugglingUntrusted3xxRedirectTollFraudSsrfAndViaRportAmplificationGuard({
      singletonHeaderCountFromToCallIdCseq: 4,
      declaredContentLengthBytes: 240,
      actualSipBodyByteLength: 240,
      sip3xxRedirectHopCount: 0,
      maxAllowed3xxRedirectHops: 2,
      redirectContactTargetInUntrustedTollOrPrivateSubnet: false,
      topmostViaSentByMatchesSourceIpPort: false,
      rfc3581ReceivedAndRportPinnedToTransportTuple: false,
    });
  assert.equal(viaRportReflectionPinned.allowed, false);
  assert.equal(
    viaRportReflectionPinned.viaSentBySpoofingOrUnpinnedRportBlocked,
    true
  );
  assert.equal(
    viaRportReflectionPinned.actionCode,
    "PIN_SIP_RESPONSE_TO_VERIFIED_RECEIVED_RPORT_TUPLE_AND_SUPPRESS_VIA_REFLECTION"
  );
  assert.equal(
    viaRportReflectionPinned.reason,
    "RFC3581_RFC3261_TOPMOST_VIA_SENT_BY_AMPLIFICATION_OR_UNPINNED_RPORT_BLOCKED"
  );

  // 4. Compliant SIP singleton headers, verified redirect policy, and symmetric Via rport pinning
  const compliantSipMessage =
    evaluateSipRfc3261Rfc3581SingletonHeaderSmugglingUntrusted3xxRedirectTollFraudSsrfAndViaRportAmplificationGuard({
      singletonHeaderCountFromToCallIdCseq: 4,
      declaredContentLengthBytes: 240,
      actualSipBodyByteLength: 240,
      sip3xxRedirectHopCount: 1,
      maxAllowed3xxRedirectHops: 2,
      redirectContactTargetInUntrustedTollOrPrivateSubnet: false,
      topmostViaSentByMatchesSourceIpPort: true,
      rfc3581ReceivedAndRportPinnedToTransportTuple: true,
    });
  assert.equal(compliantSipMessage.allowed, true);
  assert.equal(
    compliantSipMessage.actionCode,
    "ALLOW_VERIFIED_SIP_RFC3261_RFC3581_MESSAGE"
  );
  assert.equal(
    compliantSipMessage.reason,
    "SIP_RFC3261_RFC3581_SINGLETON_HEADERS_3XX_REDIRECT_AND_VIA_RPORT_VERIFIED"
  );
});

