test("evaluateWebrtcSctpRfc8841Rfc8831Rfc4960Rfc6525InitCookieReflectionStreamResetReconfigAndSackGapAckRwndDeadlockGuard aborts RFC 8841/4960 sctp-port / multi-homing / COOKIE-ECHO reflection, blocks RFC 6525 unauthenticated RE-CONFIG stream reset on audit channels, and drops malformed SACK Gap-Ack-Blocks or stalled a_rwnd=0 deadlocks (P200)", () => {
  // 1. RFC 8841 / RFC 4960 multi-homing address parameter SSRF, outbound stream amplification (>1024), or forged COOKIE-ECHO -> ABORT
  const initCookieRejected =
    evaluateWebrtcSctpRfc8841Rfc8831Rfc4960Rfc6525InitCookieReflectionStreamResetReconfigAndSackGapAckRwndDeadlockGuard({
      associationId: "sctp-assoc-9901",
      negotiatedSctpPort: 5000,
      packetDestinationPort: 5000,
      chunkType: "COOKIE-ECHO",
      containsMultiHomingAddressParams: true,
      requestedOutboundStreams: 4096,
      cookieEchoHmacValid: false,
      cookieAgeMs: 95_000,
    });
  assert.equal(
    initCookieRejected.policyCode,
    "P200-WEBRTC-SCTP-RFC8841-RFC8831-RFC4960-RFC6525-SCTP-PORT-INIT-COOKIE-ECHO-REFLECTION-UNAUTHENTICATED-STREAM-RESET-RECONFIG-AND-SACK-GAP-ACK-RWND-DEADLOCK-GUARD"
  );
  assert.equal(initCookieRejected.initOrCookieReflectionRejected, true);
  assert.equal(initCookieRejected.packetAccepted, false);
  assert.equal(
    initCookieRejected.action,
    "abort_sctp_init_or_cookie_reflection_and_strip_multihoming_params"
  );

  // 2. RFC 6525 RE-CONFIG unauthenticated stream reset or truncation of protected compliance/audit DataChannel with unacked DATA chunks
  const reconfigBlocked =
    evaluateWebrtcSctpRfc8841Rfc8831Rfc4960Rfc6525InitCookieReflectionStreamResetReconfigAndSackGapAckRwndDeadlockGuard({
      associationId: "sctp-assoc-9902",
      negotiatedSctpPort: 5000,
      packetDestinationPort: 5000,
      chunkType: "RE-CONFIG",
      reconfigExtensionNegotiated: true,
      reconfigRequestSeq: 41,
      expectedReconfigSeq: 42,
      isProtectedAuditStream: true,
      unackedDataChunksOnStream: 7,
    });
  assert.equal(reconfigBlocked.initOrCookieReflectionRejected, false);
  assert.equal(reconfigBlocked.streamResetReconfigAttackBlocked, true);
  assert.equal(reconfigBlocked.packetAccepted, false);
  assert.equal(
    reconfigBlocked.action,
    "reject_unauthenticated_reconfig_stream_reset_and_preserve_audit_channel"
  );

  // 3. RFC 4960 Section 3.3.4 malformed SACK Gap-Ack-Block (startOffset > endOffset or > maxInFlightTsnOffset) & persistent a_rwnd=0 deadlock
  const sackDeadlockBlocked =
    evaluateWebrtcSctpRfc8841Rfc8831Rfc4960Rfc6525InitCookieReflectionStreamResetReconfigAndSackGapAckRwndDeadlockGuard({
      associationId: "sctp-assoc-9903",
      negotiatedSctpPort: 5000,
      packetDestinationPort: 5000,
      chunkType: "SACK",
      sackGapAckBlocks: [
        { startOffset: 12, endOffset: 8 },
        { startOffset: 5000, endOffset: 6000 },
      ],
      maxInFlightTsnOffset: 256,
      advertisedReceiverWindowBytes: 0,
      zeroWindowDurationMs: 8_500,
    });
  assert.equal(sackDeadlockBlocked.sackGapAckOrZeroWindowBlocked, true);
  assert.equal(sackDeadlockBlocked.packetAccepted, false);
  assert.equal(
    sackDeadlockBlocked.action,
    "drop_malformed_sack_gap_ack_or_abort_stalled_zero_rwnd_association"
  );

  // 4. Valid RFC 8841 / RFC 4960 SACK chunk with monotonic in-bounds Gap-Ack-Blocks and healthy a_rwnd
  const validSctpChunk =
    evaluateWebrtcSctpRfc8841Rfc8831Rfc4960Rfc6525InitCookieReflectionStreamResetReconfigAndSackGapAckRwndDeadlockGuard({
      associationId: "sctp-assoc-9904",
      negotiatedSctpPort: 5000,
      packetDestinationPort: 5000,
      chunkType: "SACK",
      sackGapAckBlocks: [
        { startOffset: 2, endOffset: 5 },
        { startOffset: 8, endOffset: 12 },
      ],
      maxInFlightTsnOffset: 128,
      advertisedReceiverWindowBytes: 131072,
      zeroWindowDurationMs: 0,
    });
  assert.equal(validSctpChunk.packetAccepted, true);
  assert.equal(validSctpChunk.action, "accept_verified_webrtc_sctp_chunk");
  assert.equal(validSctpChunk.blockedReason, null);
});

