test("evaluateWebrtcSipIceRfc8445Rfc8838Rfc5245Rfc8863AggressiveNominationDeprecationPairPriorityOverflowConnectivityCheckTaPacingAndFrozenChecklistDeadlockGuard enforces RFC 8445 100-pair cap & Ta>=5ms pacing, rejects deprecated RFC 5245 aggressive nomination, and resolves Frozen checklist deadlocks (P222)", () => {
  // 1. Checklist pair count > 100, 64-bit priority formula overflow, or Ta < 5ms pacing flood -> 0ms drop
  const checklistOverflowOrTaBlocked =
    evaluateWebrtcSipIceRfc8445Rfc8838Rfc5245Rfc8863AggressiveNominationDeprecationPairPriorityOverflowConnectivityCheckTaPacingAndFrozenChecklistDeadlockGuard({
      sessionId: "ICE-RFC8445-SESS-222",
      candidatePairChecklistCount: 256,
      pairPriorityFormulaUnsigned64Valid: false,
      connectivityCheckIntervalTaMs: 1,
      aggressiveNominationBeforeSucceededUsed: false,
      iceTieBreakerConsistentAcrossChecks: true,
      nominatedPairFlapsPerSecond: 0,
      allChecklistPairsStuckInFrozenMs: 120,
      activeFoundationCount: 2,
      prematureFailedTransitionWhileSelectedPairAlive: false,
    });
  assert.equal(checklistOverflowOrTaBlocked.iceChecklistStateTransitionAccepted, false);
  assert.equal(
    checklistOverflowOrTaBlocked.policyCode,
    "P222-WEBRTC-SIP-ICE-RFC8445-RFC8838-RFC5245-RFC8863-AGGRESSIVE-NOMINATION-DEPRECATION-PAIR-PRIORITY-OVERFLOW-CONNECTIVITY-CHECK-TA-PACING-AND-FROZEN-CHECKLIST-DEADLOCK-GUARD"
  );
  assert.equal(
    checklistOverflowOrTaBlocked.action,
    "drop_rfc8445_ice_checklist_overflow_or_ta_pacing_violation_in_0ms"
  );
  assert.match(
    checklistOverflowOrTaBlocked.blockedReason ?? "",
    /pairCount=256/
  );

  // 2. Deprecated RFC 5245 aggressive nomination (USE-CANDIDATE before Succeeded), 64-bit tie-breaker mutation, or >2 flaps/s -> reject
  const aggressiveNominationOrTieBreakerBlocked =
    evaluateWebrtcSipIceRfc8445Rfc8838Rfc5245Rfc8863AggressiveNominationDeprecationPairPriorityOverflowConnectivityCheckTaPacingAndFrozenChecklistDeadlockGuard({
      sessionId: "ICE-RFC8445-SESS-222",
      candidatePairChecklistCount: 24,
      pairPriorityFormulaUnsigned64Valid: true,
      connectivityCheckIntervalTaMs: 20,
      aggressiveNominationBeforeSucceededUsed: true,
      iceTieBreakerConsistentAcrossChecks: false,
      nominatedPairFlapsPerSecond: 6,
      allChecklistPairsStuckInFrozenMs: 100,
      activeFoundationCount: 2,
      prematureFailedTransitionWhileSelectedPairAlive: false,
    });
  assert.equal(aggressiveNominationOrTieBreakerBlocked.iceChecklistStateTransitionAccepted, false);
  assert.equal(
    aggressiveNominationOrTieBreakerBlocked.action,
    "reject_deprecated_aggressive_nomination_or_tie_breaker_mutation"
  );
  assert.match(
    aggressiveNominationOrTieBreakerBlocked.blockedReason ?? "",
    /aggressiveNomination=true/
  );

  // 3. All checklist pairs stuck in Frozen > 3000ms with 0 active foundations, or premature Failed transition while selected pair alive -> unfreeze & quarantine
  const frozenDeadlockOrPrematureFailedBlocked =
    evaluateWebrtcSipIceRfc8445Rfc8838Rfc5245Rfc8863AggressiveNominationDeprecationPairPriorityOverflowConnectivityCheckTaPacingAndFrozenChecklistDeadlockGuard({
      sessionId: "ICE-RFC8445-SESS-222",
      candidatePairChecklistCount: 18,
      pairPriorityFormulaUnsigned64Valid: true,
      connectivityCheckIntervalTaMs: 20,
      aggressiveNominationBeforeSucceededUsed: false,
      iceTieBreakerConsistentAcrossChecks: true,
      nominatedPairFlapsPerSecond: 0,
      allChecklistPairsStuckInFrozenMs: 4800,
      activeFoundationCount: 0,
      prematureFailedTransitionWhileSelectedPairAlive: true,
    });
  assert.equal(frozenDeadlockOrPrematureFailedBlocked.iceChecklistStateTransitionAccepted, false);
  assert.equal(
    frozenDeadlockOrPrematureFailedBlocked.action,
    "unfreeze_highest_priority_foundation_and_quarantine_premature_ice_failure"
  );
  assert.match(
    frozenDeadlockOrPrematureFailedBlocked.blockedReason ?? "",
    /stuckInFrozenMs=4800ms/
  );

  // 4. Verified RFC 8445 regular nomination, 64-bit pair priority & Ta>=5ms pacing -> accepted
  const healthyIceChecklist =
    evaluateWebrtcSipIceRfc8445Rfc8838Rfc5245Rfc8863AggressiveNominationDeprecationPairPriorityOverflowConnectivityCheckTaPacingAndFrozenChecklistDeadlockGuard({
      sessionId: "ICE-RFC8445-SESS-222",
      candidatePairChecklistCount: 16,
      pairPriorityFormulaUnsigned64Valid: true,
      connectivityCheckIntervalTaMs: 20,
      aggressiveNominationBeforeSucceededUsed: false,
      iceTieBreakerConsistentAcrossChecks: true,
      nominatedPairFlapsPerSecond: 0,
      allChecklistPairsStuckInFrozenMs: 50,
      activeFoundationCount: 3,
      prematureFailedTransitionWhileSelectedPairAlive: false,
    });
  assert.equal(healthyIceChecklist.iceChecklistStateTransitionAccepted, true);
  assert.equal(
    healthyIceChecklist.action,
    "accept_verified_rfc8445_ice_checklist_nomination_and_ta_pacing"
  );
  assert.equal(healthyIceChecklist.blockedReason, null);
});

