test("P452 WebRTC & SIP RFC 8840 WebRTC ICE Pacemaker Ta timer and STUN transaction flood guard enforces 0ms sub-5ms Ta/unauth STUN flood drop and check-list explosion/rate clamping", () => {
  const clean =
    evaluateWebrtcSipRfc8840WebrtcIcePacemakerTaTimerConnectivityCheckRateLimitingAndStunTransactionFloodGuard(
      {
        sessionId: "WEBRTC-RFC8840-PACEMAKER-01",
        iceTimerTaIntervalBelow5msFloorOrNegativeMalformed: false,
        unauthenticatedStunBindingRequestFloodWithoutIceUfragPwdDetected: false,
        simultaneousCandidatePairCheckListExplosionOrDuplicateFrozenPairLoopDetected:
          false,
        stunRetransmissionRtoExponentialBackoffBypassed: false,
        activeCandidatePairsPerCheckListCount: 24,
        globalIceConnectivityCheckRatePerSecond: 40,
      },
    );
  assert.equal(clean.rfc8840IcePacemakerHealthy, true);
  assert.equal(
    clean.action,
    "allow_verified_rfc8840_webrtc_ice_pacemaker_and_stun_pacing",
  );

  const blocked =
    evaluateWebrtcSipRfc8840WebrtcIcePacemakerTaTimerConnectivityCheckRateLimitingAndStunTransactionFloodGuard(
      {
        sessionId: "WEBRTC-RFC8840-PACEMAKER-ATTACK-99",
        iceTimerTaIntervalBelow5msFloorOrNegativeMalformed: true,
        unauthenticatedStunBindingRequestFloodWithoutIceUfragPwdDetected: true,
        simultaneousCandidatePairCheckListExplosionOrDuplicateFrozenPairLoopDetected:
          true,
        stunRetransmissionRtoExponentialBackoffBypassed: true,
        activeCandidatePairsPerCheckListCount: 450,
        globalIceConnectivityCheckRatePerSecond: 1800,
      },
    );
  assert.equal(
    blocked.policyCode,
    "P452-WEBRTC-SIP-RFC8840-WEBRTC-ICE-PACEMAKER-TA-TIMER-CONNECTIVITY-CHECK-RATE-LIMITING-AND-STUN-TRANSACTION-FLOOD-GUARD",
  );
  assert.equal(blocked.rfc8840IcePacemakerHealthy, false);
  assert.equal(blocked.sub5msTaTimerOrUnauthStunFloodDropped0ms, true);
  assert.equal(
    blocked.action,
    "drop_sub5ms_ice_ta_timer_or_unauth_stun_binding_flood_0ms",
  );
});


















